result = 0
for i in range(len(operator)):
    if operator[i] == '+':
        result += operand[i]
    elif operator[i] == '-':
        result -= operand[i]
    elif operator[i] == '*':
        result *= operand[i]
    elif operator[i] == '/':
        result //= operand[i]
    elif operator[i] == '**':
        result **= operand[i]
    else:
        raise ValueError("Invalid operator")

return result
